Successfully created and wrote to new file: /app/output/index.html. Here is the updated code:
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MedBook — Find and Book Top Doctors Instantly</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    <style>
        :root {
            --primary-blue: #0066FF;
            --primary-blue-hover: #0052cc;
            --navy: #1B1464;
            --accent-teal: #10B981;
            --accent-teal-hover: #059669;
            --accent-yellow: #FFD930;
            --bg-white: #FFFFFF;
            --bg-light: #F8FAFC;
            --bg-muted: #F1F5F9;
            --text-main: #0F172A;
            --text-muted: #475569;
            --text-light: #94A3B8;
            --border-color: #E2E8F0;

            --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
            --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
            --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
            --shadow-hero: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);

            --radius-md: 12px;
            --radius-lg: 16px;
            --radius-full: 9999px;

            --transition: all 0.2s ease-in-out;
            --container-width: 1200px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: 'Inter', sans-serif;
            color: var(--text-main);
            background-color: var(--bg-white);
            line-height: 1.6;
            -webkit-font-smoothing: antialiased;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        ul {
            list-style: none;
        }

        button, input, select {
            font-family: inherit;
            border: none;
            outline: none;
            background: none;
        }

        button {
            cursor: pointer;
        }

        .container {
            width: 100%;
            max-width: var(--container-width);
            margin: 0 auto;
            padding: 0 24px;
        }

        /* Typography */
        h1, h2, h3, h4 {
            color: var(--navy);
            line-height: 1.2;
            font-weight: 800;
        }

        h1 { font-size: 3.5rem; letter-spacing: -0.02em; }
        h2 { font-size: 2.5rem; letter-spacing: -0.01em; margin-bottom: 1rem; }
        h3 { font-size: 1.25rem; }

        p { color: var(--text-muted); font-size: 1.125rem; }

        .text-center { text-align: center; }

        /* Buttons */
        .btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 12px 24px;
            border-radius: var(--radius-full);
            font-weight: 600;
            font-size: 1rem;
            transition: var(--transition);
        }

        .btn-primary {
            background-color: var(--accent-teal);
            color: white;
            box-shadow: 0 4px 6px rgba(16, 185, 129, 0.2);
        }

        .btn-primary:hover {
            background-color: var(--accent-teal-hover);
            transform: translateY(-1px);
            box-shadow: 0 6px 8px rgba(16, 185, 129, 0.3);
        }

        .btn-secondary {
            background-color: var(--bg-white);
            color: var(--primary-blue);
            border: 2px solid var(--border-color);
        }

        .btn-secondary:hover {
            border-color: var(--primary-blue);
            color: var(--primary-blue-hover);
        }

        .btn-nav {
            padding: 10px 20px;
        }

        /* Header & Nav */
        header {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            background-color: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(8px);
            border-bottom: 1px solid var(--border-color);
            z-index: 100;
            height: 80px;
            display: flex;
            align-items: center;
        }

        .nav-container {
            display: flex;
            justify-content: space-between;
            align-items: center;
            width: 100%;
        }

        .logo {
            font-size: 1.75rem;
            font-weight: 800;
            color: var(--primary-blue);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .logo svg {
            width: 32px;
            height: 32px;
            fill: var(--primary-blue);
        }

        .desktop-nav {
            display: flex;
            align-items: center;
            gap: 32px;
        }

        .nav-links {
            display: flex;
            gap: 24px;
            font-weight: 500;
            color: var(--text-main);
        }

        .nav-links a:hover {
            color: var(--primary-blue);
        }

        .nav-actions {
            display: flex;
            gap: 16px;
            align-items: center;
        }

        .nav-login {
            font-weight: 600;
            color: var(--primary-blue);
        }

        .hamburger {
            display: none;
            background: none;
            border: none;
            cursor: pointer;
            padding: 8px;
        }

        .hamburger svg {
            width: 24px;
            height: 24px;
            stroke: var(--navy);
        }

        /* Hero Section */
        .hero {
            padding: 160px 0 100px;
            background: linear-gradient(135deg, #F0F7FF 0%, #FFFFFF 100%);
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: -100px;
            right: -100px;
            width: 400px;
            height: 400px;
            background: radial-gradient(circle, rgba(0,102,255,0.05) 0%, rgba(255,255,255,0) 70%);
            border-radius: 50%;
        }

        .hero h1 {
            max-width: 800px;
            margin: 0 auto 24px;
        }

        .hero p {
            max-width: 680px;
            margin: 0 auto 48px;
            font-size: 1.25rem;
        }

        /* Search Component */
        .search-wrapper {
            max-width: 1000px;
            margin: 0 auto;
            background: var(--bg-white);
            border-radius: var(--radius-full);
            box-shadow: var(--shadow-hero);
            padding: 8px;
            display: flex;
            align-items: center;
            position: relative;
            border: 1px solid var(--border-color);
        }

        .search-field {
            flex: 1;
            display: flex;
            align-items: center;
            padding: 12px 24px;
            gap: 16px;
            position: relative;
            border-radius: var(--radius-full);
            transition: var(--transition);
        }

        .search-field:hover {
            background-color: var(--bg-muted);
        }

        .search-field:focus-within {
            background-color: var(--bg-white);
            box-shadow: 0 0 0 2px var(--primary-blue);
            z-index: 10;
        }

        .search-icon {
            color: var(--text-light);
            display: flex;
            flex-shrink: 0;
        }

        .search-icon svg {
            width: 24px;
            height: 24px;
            stroke: currentColor;
            stroke-width: 2;
            fill: none;
        }

        .input-group {
            display: flex;
            flex-direction: column;
            flex: 1;
            text-align: left;
        }

        .input-group label {
            font-size: 0.75rem;
            font-weight: 700;
            color: var(--navy);
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 2px;
        }

        .input-group input, .input-group select {
            width: 100%;
            font-size: 1rem;
            color: var(--text-main);
            background: transparent;
            cursor: pointer;
        }

        .input-group input::placeholder, .input-group select:invalid {
            color: var(--text-light);
        }

        .input-group input:focus {
            cursor: text;
        }

        .search-divider {
            width: 1px;
            height: 40px;
            background-color: var(--border-color);
            margin: 0 8px;
        }

        .search-btn-wrapper {
            padding-left: 8px;
        }

        .btn-hero-search {
            height: 56px;
            padding: 0 40px;
            font-size: 1.125rem;
            gap: 8px;
        }

        /* Autocomplete Dropdown */
        .autocomplete-dropdown {
            position: absolute;
            top: calc(100% + 12px);
            left: 0;
            width: 350px;
            background: var(--bg-white);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-lg);
            border: 1px solid var(--border-color);
            padding: 12px 0;
            opacity: 0;
            visibility: hidden;
            transform: translateY(-10px);
            transition: var(--transition);
            z-index: 50;
        }

        .search-field:focus-within .autocomplete-dropdown.active,
        .autocomplete-dropdown:hover {
            opacity: 1;
            visibility: visible;
            transform: translateY(0);
        }

        .dropdown-section {
            padding: 8px 24px;
            font-size: 0.75rem;
            font-weight: 700;
            color: var(--text-light);
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }

        .dropdown-item {
            padding: 12px 24px;
            display: flex;
            align-items: center;
            gap: 16px;
            cursor: pointer;
            transition: background 0.1s;
        }

        .dropdown-item:hover {
            background-color: var(--bg-muted);
        }

        .dropdown-item .icon-bg {
            width: 32px;
            height: 32px;
            background-color: #E0E7FF;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--primary-blue);
        }

        .dropdown-item .icon-bg svg {
            width: 18px;
            height: 18px;
            stroke: currentColor;
            stroke-width: 2;
            fill: none;
        }

        .dropdown-item span {
            font-weight: 500;
            color: var(--text-main);
        }

        /* Stats Section */
        .stats {
            padding: 60px 0;
            background-color: var(--bg-white);
            border-bottom: 1px solid var(--border-color);
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 24px;
            text-align: center;
        }

        .stat-item h3 {
            font-size: 2.5rem;
            color: var(--primary-blue);
            margin-bottom: 8px;
            font-weight: 800;
        }

        .stat-item p {
            font-size: 1rem;
            font-weight: 500;
            color: var(--navy);
            margin: 0;
        }

        /* Specialties Section */
        .specialties {
            padding: 100px 0;
            background-color: var(--bg-light);
        }

        .section-header {
            text-align: center;
            margin-bottom: 56px;
        }

        .specialty-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
            gap: 24px;
        }

        .specialty-card {
            background: var(--bg-white);
            border-radius: var(--radius-lg);
            padding: 32px;
            border: 1px solid var(--border-color);
            transition: var(--transition);
            display: flex;
            align-items: flex-start;
            gap: 20px;
            cursor: pointer;
            text-decoration: none;
            color: inherit;
        }

        .specialty-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-md);
            border-color: var(--primary-blue);
        }

        .specialty-icon {
            width: 56px;
            height: 56px;
            background-color: #E0E7FF;
            border-radius: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--primary-blue);
            flex-shrink: 0;
        }

        .specialty-icon svg {
            width: 28px;
            height: 28px;
            stroke: currentColor;
            stroke-width: 1.5;
            fill: none;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .specialty-card:hover .specialty-icon {
            background-color: var(--primary-blue);
            color: var(--bg-white);
        }

        .specialty-content h3 {
            margin-bottom: 8px;
            font-size: 1.25rem;
            color: var(--navy);
        }

        .specialty-content p {
            font-size: 0.95rem;
            margin: 0;
            line-height: 1.5;
        }

        /* How It Works */
        .how-it-works {
            padding: 100px 0;
            background-color: var(--bg-white);
        }

        .steps-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 40px;
            margin-top: 56px;
        }

        .step {
            text-align: center;
            position: relative;
        }

        .step:not(:last-child)::after {
            content: '';
            position: absolute;
            top: 40px;
            right: -20px;
            width: 40px;
            height: 2px;
            background-image: linear-gradient(to right, var(--border-color) 40%, transparent 40%);
            background-size: 10px 100%;
            background-repeat: repeat-x;
        }

        .step-number {
            width: 80px;
            height: 80px;
            background-color: var(--bg-light);
            color: var(--primary-blue);
            font-size: 2rem;
            font-weight: 800;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 24px;
            border: 4px solid var(--bg-white);
            box-shadow: var(--shadow-sm);
        }

        .step h3 {
            margin-bottom: 12px;
            font-size: 1.25rem;
        }

        .step p {
            font-size: 1rem;
            margin: 0;
        }

        /* Testimonials */
        .testimonials {
            padding: 100px 0;
            background-color: var(--navy);
            color: var(--bg-white);
        }

        .testimonials h2 {
            color: var(--bg-white);
        }

        .testimonials p.subtitle {
            color: #94A3B8;
        }

        .testimonial-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
            margin-top: 56px;
        }

        .testimonial-card {
            background-color: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: var(--radius-lg);
            padding: 32px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }

        .stars {
            color: var(--accent-yellow);
            margin-bottom: 24px;
            display: flex;
            gap: 4px;
        }

        .stars svg {
            width: 20px;
            height: 20px;
            fill: currentColor;
        }

        .quote {
            font-size: 1.125rem;
            line-height: 1.6;
            margin-bottom: 32px;
            font-style: italic;
            color: #F8FAFC;
        }

        .author-info {
            display: flex;
            align-items: center;
            gap: 16px;
        }

        .author-avatar {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            background-color: var(--primary-blue);
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: 1.25rem;
        }

        .author-details h4 {
            color: var(--bg-white);
            margin: 0 0 4px 0;
            font-size: 1rem;
        }

        .author-details span {
            color: #94A3B8;
            font-size: 0.875rem;
        }

        /* App Promo */
        .app-promo {
            padding: 100px 0;
            background-color: var(--bg-white);
        }

        .app-promo-inner {
            background-color: var(--primary-blue);
            border-radius: 24px;
            padding: 64px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            color: var(--bg-white);
            position: relative;
            overflow: hidden;
        }

        .app-promo-content {
            max-width: 500px;
            z-index: 2;
        }

        .app-promo-content h2 {
            color: var(--bg-white);
        }

        .app-promo-content p {
            color: #E0E7FF;
            margin-bottom: 32px;
        }

        .app-features {
            margin-bottom: 40px;
        }

        .app-features li {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-bottom: 16px;
            font-size: 1.125rem;
            color: #F8FAFC;
        }

        .app-features li svg {
            width: 24px;
            height: 24px;
            fill: none;
            stroke: var(--accent-yellow);
            stroke-width: 2;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .store-buttons {
            display: flex;
            gap: 16px;
        }

        .store-btn {
            background: #000000;
            color: white;
            padding: 12px 24px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            gap: 12px;
            text-decoration: none;
            transition: opacity 0.2s;
        }

        .store-btn:hover {
            opacity: 0.8;
        }

        .store-btn svg {
            width: 28px;
            height: 28px;
            fill: white;
        }

        .store-btn-text {
            display: flex;
            flex-direction: column;
            line-height: 1.2;
        }

        .store-btn-text small {
            font-size: 0.75rem;
        }

        .store-btn-text strong {
            font-size: 1.125rem;
            font-weight: 600;
        }

        .app-promo-image {
            z-index: 2;
            position: relative;
            width: 320px;
            height: 600px;
            background: white;
            border-radius: 40px;
            border: 8px solid #0F172A;
            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
            margin-top: -100px;
            margin-bottom: -100px;
            overflow: hidden;
            display: flex;
            flex-direction: column;
        }

        .app-mockup-header {
            background: var(--primary-blue);
            height: 120px;
            border-radius: 0 0 24px 24px;
            padding: 24px;
            color: white;
        }

        .app-mockup-body {
            padding: 24px;
            flex: 1;
            background: #F8FAFC;
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .mockup-skeleton {
            background: white;
            border-radius: 12px;
            height: 80px;
            width: 100%;
            box-shadow: var(--shadow-sm);
        }

        .app-promo-inner::after {
            content: '';
            position: absolute;
            top: 0;
            right: 10%;
            width: 600px;
            height: 600px;
            background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 70%);
            border-radius: 50%;
            z-index: 1;
        }

        /* Footer */
        footer {
            background-color: var(--navy);
            color: #94A3B8;
            padding: 80px 0 40px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
            gap: 40px;
            margin-bottom: 64px;
        }

        .footer-brand .logo {
            color: var(--bg-white);
            margin-bottom: 24px;
        }

        .footer-brand .logo svg {
            fill: var(--bg-white);
        }

        .footer-col h4 {
            color: var(--bg-white);
            font-size: 1rem;
            margin-bottom: 24px;
        }

        .footer-links {
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .footer-links a {
            transition: color 0.2s;
        }

        .footer-links a:hover {
            color: var(--bg-white);
        }

        .footer-bottom {
            padding-top: 32px;
            border-top: 1px solid rgba(255, 255, 255, 0.1);
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 0.875rem;
        }

        /* Mobile Menu */
        .mobile-menu {
            position: fixed;
            top: 0;
            right: -100%;
            width: 300px;
            height: 100vh;
            background-color: var(--bg-white);
            z-index: 1000;
            box-shadow: -10px 0 20px rgba(0,0,0,0.1);
            transition: right 0.3s ease-in-out;
            padding: 24px;
            display: flex;
            flex-direction: column;
        }

        .mobile-menu.open {
            right: 0;
        }

        .mobile-menu-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 40px;
        }

        .close-menu {
            background: none;
            border: none;
            cursor: pointer;
            color: var(--text-main);
        }

        .close-menu svg {
            width: 24px;
            height: 24px;
        }

        .mobile-links {
            display: flex;
            flex-direction: column;
            gap: 24px;
            font-size: 1.25rem;
            font-weight: 500;
            margin-bottom: auto;
        }

        .mobile-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(15, 23, 42, 0.5);
            backdrop-filter: blur(4px);
            z-index: 999;
            opacity: 0;
            visibility: hidden;
            transition: opacity 0.3s ease-in-out;
        }

        .mobile-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        /* Responsive Design */
        @media (max-width: 1024px) {
            h1 { font-size: 3rem; }
            .search-wrapper { border-radius: 24px; flex-direction: column; padding: 16px; background: var(--bg-white); }
            .search-field { width: 100%; border-radius: 12px; }
            .search-divider { width: 100%; height: 1px; margin: 8px 0; }
            .search-btn-wrapper { width: 100%; padding: 0; margin-top: 16px; }
            .btn-hero-search { width: 100%; border-radius: 12px; }
            .stats-grid { grid-template-columns: repeat(2, 1fr); }
            .app-promo-inner { flex-direction: column; text-align: center; padding: 48px 24px; gap: 48px; }
            .app-features li { justify-content: center; }
            .store-buttons { justify-content: center; }
            .app-promo-image { margin: 0; }
            .footer-grid { grid-template-columns: 1fr 1fr; }
            .footer-brand { grid-column: 1 / -1; }
        }

        @media (max-width: 768px) {
            h1 { font-size: 2.5rem; }
            .desktop-nav, .nav-actions { display: none; }
            .hamburger { display: block; }
            .steps-grid, .testimonial-grid { grid-template-columns: 1fr; gap: 48px; }
            .step:not(:last-child)::after { display: none; }
            .stats-grid { grid-template-columns: 1fr; gap: 32px; }
            .store-buttons { flex-direction: column; }
            .hero { padding: 120px 0 60px; }
            .autocomplete-dropdown { width: 100%; position: static; box-shadow: none; border: none; padding: 0; margin-top: 8px; }
            .search-field:focus-within .autocomplete-dropdown.active, .autocomplete-dropdown:hover { position: relative; }
        }
    </style>
</head>
<body>

    <!-- Header Navigation -->
    <header>
        <div class="container nav-container">
